import { parseBoardCode } from '../deck.ts';
import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import { decodeSnapshot } from '../snapshot.ts';
import { isJsonObject, isNonnegativeSafeInteger, parseJson } from '../saved-format.ts';

export interface Score {
  moves: number;
  elapsedMs: number;
}
export interface Match {
  players: [number | null, number | null];
  scores: [Score | null, Score | null];
  winner: number | null;
  boardCode: string | null;
}
export type Phase = 'ready' | 'playing' | 'turnDone' | 'matchDone' | 'complete';
export interface TournamentData {
  version: 1;
  names: string[];
  rounds: Match[][];
  round: number;
  match: number;
  turn: number;
  phase: Phase;
  snapshot: string | null;
}

export function createTournament(names: string[]): TournamentData {
  const rounds: Match[][] = [];
  for (let count = names.length / 2; count >= 1; count /= 2) {
    rounds.push(
      Array.from({ length: count }, (_, index) => ({
        players: rounds.length === 0 ? [index * 2, index * 2 + 1] : [null, null],
        scores: [null, null],
        winner: null,
        boardCode: null,
      })),
    );
  }
  return { version: 1, names, rounds, round: 0, match: 0, turn: 0, phase: 'ready', snapshot: null };
}

export function currentMatch(data: TournamentData): Match {
  const match = data.rounds[data.round]?.[data.match];
  if (!match) throw new Error('Invalid tournament position.');
  return match;
}

export function updateMatch(data: TournamentData, match: Match): TournamentData {
  return {
    ...data,
    rounds: data.rounds.map((round, r) =>
      r === data.round ? round.map((item, m) => (m === data.match ? match : item)) : round,
    ),
  };
}

export function recordScore(data: TournamentData, score: Score): TournamentData {
  const match = currentMatch(data);
  const scores: [Score | null, Score | null] =
    data.turn === 0 ? [score, null] : [match.scores[0], score];
  if (data.turn === 0)
    return { ...updateMatch(data, { ...match, scores }), phase: 'turnDone', snapshot: null };
  const first = scores[0];
  if (!first) throw new Error('Missing first score.');
  const comparison = first.moves - score.moves || first.elapsedMs - score.elapsedMs;
  if (comparison === 0)
    return {
      ...updateMatch(data, { ...match, scores: [null, null], boardCode: null }),
      phase: 'ready',
      turn: 0,
      snapshot: null,
    };
  const winner = match.players[comparison < 0 ? 0 : 1];
  if (winner === null) throw new Error('Missing player.');
  return { ...updateMatch(data, { ...match, scores, winner }), phase: 'matchDone', snapshot: null };
}

export function advanceMatch(data: TournamentData): TournamentData {
  const winner = currentMatch(data).winner;
  if (winner === null) throw new Error('Missing winner.');
  if (data.round === data.rounds.length - 1) return { ...data, phase: 'complete' };
  const nextRound = data.round + 1;
  const nextMatch = Math.floor(data.match / 2);
  const rounds = data.rounds.map((round, r) =>
    r !== nextRound
      ? round
      : round.map((match, m) => {
          if (m !== nextMatch) return match;
          const players: [number | null, number | null] = [...match.players];
          players[data.match % 2] = winner;
          return { ...match, players };
        }),
  );
  const atEnd = data.match + 1 === data.rounds[data.round]?.length;
  return {
    ...data,
    rounds,
    round: atEnd ? nextRound : data.round,
    match: atEnd ? 0 : data.match + 1,
    turn: 0,
    phase: 'ready',
  };
}

function isScore(value: unknown): value is Score {
  return (
    isJsonObject(value) &&
    isNonnegativeSafeInteger(value.moves) &&
    value.moves <= MOVES_MAX &&
    isNonnegativeSafeInteger(value.elapsedMs) &&
    value.elapsedMs <= ELAPSED_MAX_MS
  );
}

export function readTournament(text: string): TournamentData | null {
  const value = text.length <= 1_000_000 ? parseJson(text) : undefined;
  if (
    !isJsonObject(value) ||
    value.version !== 1 ||
    !Array.isArray(value.names) ||
    ![4, 8].includes(value.names.length) ||
    !value.names.every(
      (name: unknown) => typeof name === 'string' && name.trim().length > 0 && name.length <= 100,
    ) ||
    !Array.isArray(value.rounds) ||
    value.rounds.length !== Math.log2(value.names.length) ||
    !isNonnegativeSafeInteger(value.round) ||
    !isNonnegativeSafeInteger(value.match) ||
    (value.turn !== 0 && value.turn !== 1) ||
    !['ready', 'playing', 'turnDone', 'matchDone', 'complete'].includes(String(value.phase)) ||
    !(value.snapshot === null || typeof value.snapshot === 'string')
  )
    return null;
  const names: string[] = value.names;
  const rounds: Match[][] = [];
  for (let r = 0; r < value.rounds.length; r++) {
    const input: unknown = value.rounds[r];
    if (!Array.isArray(input) || input.length !== names.length / 2 ** (r + 1)) return null;
    const round: Match[] = [];
    for (const item of input) {
      if (
        !isJsonObject(item) ||
        !Array.isArray(item.players) ||
        item.players.length !== 2 ||
        !item.players.every(
          (p: unknown) => p === null || (isNonnegativeSafeInteger(p) && p < names.length),
        ) ||
        !Array.isArray(item.scores) ||
        item.scores.length !== 2 ||
        !item.scores.every((s: unknown) => s === null || isScore(s)) ||
        !(
          item.winner === null ||
          (isNonnegativeSafeInteger(item.winner) && item.players.includes(item.winner))
        ) ||
        !(
          item.boardCode === null ||
          (typeof item.boardCode === 'string' && parseBoardCode(item.boardCode))
        )
      )
        return null;
      round.push({
        players: [item.players[0], item.players[1]],
        scores: [item.scores[0], item.scores[1]],
        winner: item.winner,
        boardCode: item.boardCode,
      });
    }
    rounds.push(round);
  }
  const round = value.rounds[value.round];
  if (!Array.isArray(round) || value.match >= round.length) return null;
  const phase = value.phase;
  if (
    phase !== 'ready' &&
    phase !== 'playing' &&
    phase !== 'turnDone' &&
    phase !== 'matchDone' &&
    phase !== 'complete'
  )
    return null;
  const data: TournamentData = {
    version: 1,
    names,
    rounds,
    round: value.round,
    match: value.match,
    turn: value.turn,
    phase,
    snapshot: value.snapshot,
  };
  const match = currentMatch(data);
  if (
    match.players.some((p) => p === null) ||
    (phase === 'playing' && (!match.boardCode || !data.snapshot)) ||
    (phase === 'turnDone' && (!match.scores[0] || data.turn !== 0)) ||
    ((phase === 'matchDone' || phase === 'complete') && match.winner === null)
  )
    return null;
  if (data.snapshot) {
    const game = decodeSnapshot(data.snapshot);
    if (!game || game.boardCode !== match.boardCode || phase !== 'playing') return null;
  }
  return data;
}
import { useEffect, useRef, useState } from 'react';
import { freshBoardCode } from '../session/fresh-board.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { TournamentTurn } from './TournamentTurn.tsx';
import {
  advanceMatch,
  createTournament,
  currentMatch,
  readTournament,
  recordScore,
  updateMatch,
} from './tournament.ts';
import type { Score, TournamentData } from './tournament.ts';
import './tournament.css';

const HISTORY_KEY = 'neon-pairs.tournaments.v1';

function readHistory(): TournamentData[] {
  try {
    const values: unknown = JSON.parse(localStorage.getItem(HISTORY_KEY) ?? '[]');
    if (!Array.isArray(values)) return [];
    return values.flatMap((value: unknown) => {
      const item = readTournament(JSON.stringify(value));
      return item?.phase === 'complete' ? [item] : [];
    });
  } catch {
    return [];
  }
}

interface Props {
  size: number;
  back(): void;
}
export function Tournament({ size, back }: Props) {
  const [count, setCount] = useState(4);
  const [names, setNames] = useState<string[]>(Array(8).fill(''));
  const [data, setData] = useState<TournamentData | null>(null);
  const [history, setHistory] = useState(readHistory);
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState('');
  const turn = useRef<{ exportSnapshot(): string }>(null);
  const match = data ? currentMatch(data) : null;
  useEffect(() => {
    if (!data || data.phase !== 'complete') return;
    setHistory((old) => {
      if (old.some((item) => JSON.stringify(item) === JSON.stringify(data))) return old;
      const next = [data, ...old];
      try {
        localStorage.setItem(HISTORY_KEY, JSON.stringify(next));
      } catch {
        /* Storage can be unavailable. */
      }
      return next;
    });
  }, [data]);

  function start(): void {
    const players = names.slice(0, count).map((name) => name.trim());
    if (players.some((name) => !name)) {
      setNotice('Enter a name for every player.');
      return;
    }
    setNotice('');
    setData(createTournament(players));
  }
  function startTurn(): void {
    if (!data || !match) return;
    const boardCode = match.boardCode ?? freshBoardCode(size);
    setNotice('');
    setData({ ...updateMatch(data, { ...match, boardCode }), phase: 'playing', snapshot: null });
  }
  function finished(score: Score): void {
    setData((old) => {
      if (!old || old.phase !== 'playing') return old;
      const next = recordScore(old, score);
      if (next.phase === 'ready')
        setNotice('The scores are tied. Play the match again on a new deal.');
      return next.phase === 'matchDone' && next.round === next.rounds.length - 1
        ? { ...next, phase: 'complete' }
        : next;
    });
  }
  function exportTournament(): void {
    if (!data) {
      setJson(JSON.stringify({ version: 1, setup: true, count, names }, null, 2));
    } else {
      const snapshot = data.phase === 'playing' ? turn.current?.exportSnapshot() : null;
      if (data.phase === 'playing' && !snapshot) {
        setNotice('The turn is still starting. Try again.');
        return;
      }
      setJson(JSON.stringify({ ...data, snapshot: snapshot ?? null }, null, 2));
    }
    setNotice('Tournament exported to the Tournament JSON box.');
  }
  function loadTournament(): void {
    const loaded = readTournament(json);
    if (loaded) {
      setData(loaded);
      setNotice('Tournament loaded.');
      return;
    }
    try {
      const setup: unknown = JSON.parse(json);
      if (
        typeof setup === 'object' &&
        setup !== null &&
        'version' in setup &&
        setup.version === 1 &&
        'setup' in setup &&
        setup.setup === true &&
        'count' in setup &&
        (setup.count === 4 || setup.count === 8) &&
        'names' in setup &&
        Array.isArray(setup.names) &&
        setup.names.length === 8 &&
        setup.names.every((name: unknown) => typeof name === 'string' && name.length <= 100)
      ) {
        setNames(setup.names);
        setCount(setup.count);
        setData(null);
        setNotice('Tournament setup loaded.');
        return;
      }
    } catch {
      /* Show the same message for all invalid input. */
    }
    setNotice('Invalid tournament JSON.');
  }
  return (
    <main className="tournament">
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Tournament</h1>
      </header>
      {!data ? (
        <>
          <p>
            Share one device and play the same deal in each match. Fewer moves wins; time breaks a
            tie. If both are equal, replay the match.
          </p>
          <div className="tournament-setup">
            <label htmlFor="players">Players</label>
            <select
              id="players"
              className="control"
              value={count}
              onChange={(event) => setCount(Number(event.currentTarget.value))}
            >
              <option value={4}>4</option>
              <option value={8}>8</option>
            </select>
            <div className="player-inputs">
              {names.slice(0, count).map((name, index) => (
                <div key={index}>
                  <label htmlFor={`player-${index}`}>Player {index + 1}</label>
                  <input
                    id={`player-${index}`}
                    className="control"
                    value={name}
                    maxLength={100}
                    onChange={(event) => {
                      const value = event.currentTarget.value;
                      setNames((old) => old.map((item, i) => (i === index ? value : item)));
                    }}
                  />
                </div>
              ))}
            </div>
            <p>
              Board size: {size}x{size}
            </p>
            <div className="tournament-actions">
              <button className="control" onClick={start}>
                Start tournament
              </button>
              <button className="control" onClick={back}>
                Back to game
              </button>
            </div>
          </div>
          <section>
            <h2>Past tournaments</h2>
            {history.length === 0 ? (
              <p>No finished tournaments yet.</p>
            ) : (
              <ul>
                {history.map((item, index) => (
                  <li key={index}>
                    <button
                      className="control"
                      onClick={() => {
                        setData(item);
                        setNotice('');
                      }}
                    >
                      Champion: {item.names[currentMatch(item).winner ?? 0]}
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </section>
        </>
      ) : (
        <>
          {data.phase === 'complete' ? (
            <>
              <h2>Champion: {data.names[match?.winner ?? 0]}</h2>
              <button className="control" onClick={back}>
                Back to game
              </button>
            </>
          ) : (
            <>
              <p className="now-playing">
                Now playing: {data.names[match?.players[data.turn] ?? 0]}
              </p>
              <div className="tournament-actions">
                {data.phase === 'ready' && (
                  <button className="control" onClick={startTurn}>
                    Start turn
                  </button>
                )}
                {data.phase === 'turnDone' && (
                  <button
                    className="control"
                    onClick={() => setData({ ...data, turn: 1, phase: 'ready' })}
                  >
                    Next turn
                  </button>
                )}
                {data.phase === 'matchDone' && (
                  <button className="control" onClick={() => setData(advanceMatch(data))}>
                    Next match
                  </button>
                )}
                <button
                  className="control"
                  onClick={() => {
                    setData(null);
                    setNotice('Tournament ended.');
                  }}
                >
                  Leave tournament
                </button>
              </div>
              {data.phase === 'playing' && match?.boardCode && (
                <TournamentTurn
                  key={`${data.round}-${data.match}-${data.turn}`}
                  code={match.boardCode}
                  snapshot={data.snapshot}
                  finished={finished}
                  ref={turn}
                />
              )}
            </>
          )}
          <section>
            <h2>Bracket</h2>
            <div className="bracket">
              {data.rounds.map((round, r) => (
                <div className="bracket-round" key={r}>
                  <h3>{r === data.rounds.length - 1 ? 'Final' : `Round ${r + 1}`}</h3>
                  {round.map((item, m) => (
                    <div className="bracket-match" key={m}>
                      <h4>Match {m + 1}</h4>
                      {item.players.map((player, p) => (
                        <p key={p}>
                          {player === null ? 'To be decided' : data.names[player]}:{' '}
                          {item.scores[p]
                            ? `${item.scores[p]?.moves} moves, ${formatElapsed(item.scores[p]?.elapsedMs ?? 0)}`
                            : '—'}
                        </p>
                      ))}
                      <p>Winner: {item.winner === null ? '—' : data.names[item.winner]}</p>
                    </div>
                  ))}
                </div>
              ))}
            </div>
          </section>
        </>
      )}
      <section className="tournament-transfer">
        <h2>Tournament JSON</h2>
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control"
          value={json}
          onChange={(event) => setJson(event.currentTarget.value)}
          rows={6}
        />
        <div className="tournament-actions">
          <button className="control" onClick={exportTournament}>
            Export tournament
          </button>
          <button className="control" onClick={loadTournament}>
            Load tournament
          </button>
        </div>
      </section>
      <p role="status" aria-live="polite">
        {notice}
      </p>
    </main>
  );
}

